          id: props.id,
          value: props.value,
          required: ""
        }
      });

      const text = createElement("span", {
        className: "option-text",
        text: props.label
      });

      return createElement("label", {
        className: "option",
        attributes: { for: props.id },
        children: [input, text]
      });
    }

    function NotificationPreferenceField() {
      const options = createElement("div", {
        className: "options",
        children: [
          RadioOption({ id: "notification-email", value: "Email", label: "Email" }),
          RadioOption({ id: "notification-sms", value: "SMS", label: "SMS" }),
          RadioOption({
            id: "notification-push",
            value: "Push Notifications",
            label: "Push Notifications"
          })
        ]
      });

      const fieldset = createElement("fieldset", {
        children: [
          createElement("legend", {
            text: "How do you prefer to receive notifications?"
          }),
          options
        ]
      });

      return createElement("div", {
        className: "form-field",
        children: [fieldset]
      });
    }

    function SubmitButton() {
      return createElement("button", {
        text: "Submit",
        attributes: { type: "submit" }
      });
    }

    function FormSection() {
      const status = createElement("p", {
        className: "status",
        attributes: {
          id: "form-status",
          "aria-live": "polite"
        }
      });

      const form = createElement("form", {
        attributes: { novalidate: "" },
        children: [
          NotificationPreferenceField(),
          createElement("div", {
            className: "actions",
            children: [SubmitButton(), status]
          })
        ]
      });

      form.addEventListener("submit", function (event) {
        event.preventDefault();

        const selected = form.querySelector('input[name="notificationPreference"]:checked');
        if (!selected) {
          status.textContent = "Please choose one notification method before submitting.";
          const firstOption = form.querySelector('input[name="notificationPreference"]');
          if (firstOption) {
            firstOption.focus();
          }
          return;
        }

        status.textContent = "Preference saved: " + selected.value + ".";
      });

      return form;
    }

    function App() {
      return createElement("main", {
        attributes: { id: "main-content" },
        children: [
          createElement("section", {
            className: "card",
            children: [
