                 className: "eyebrow",
                 text: "Preferences"
               }),
               createElement("h1", {
                 text: "Notification settings"
               }),
               createElement("p", {
                 className: "intro",
                 text: "Choose the single notification channel you want us to use for updates and alerts."
               }),
               FormSection()
             ]
           })
         ]
       });
     }

     document.getElementById("app").appendChild(App());
   </script>
